+			diags = diags.Append(validateImportTargetExpansion(n.Config, to, imp.Config.To))
+			if diags.HasErrors() {
+				return diags
+			}
+
+			_, evalDiags := evaluateImportIdExpression(imp.Config.ID, ctx, EvalDataForNoInstanceKey, true)
+			diags = diags.Append(evalDiags)
+			if diags.HasErrors() {
+				return diags
+			}
+		}
+	}
+
+	return diags
+}
